        require(role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE(), "bad role");
        bool reverted;
        c.grantRole(role, account);
        // at this point the test has the role; renounce it so it is no longer an admin
        c.renounceRole(c.TIMELOCK_ADMIN_ROLE(), address(this));
        try c.grantRole(role, account) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && !c.hasRole(role, account) == false ? (reverted && c.hasRole(role, account)) : (reverted && !c.hasRole(role, account)));
    }
    receive() external payable {}
