contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 salt, uint256 delay) public {
        require(delay >= c.getMinDelay() && delay > 0);

        // Grant this contract (deployer/admin of c) the proposer role.
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);

        // Schedule: makes the operation pending.
        c.schedule(address(this), 0, "", bytes32(0), salt, delay);
        bool pendingBefore = c.isOperation(id);

        // Cancel: removes the operation entirely.
        c.cancel(id);

        assert(
            pendingBefore &&
            !c.isOperation(id) &&
            !c.isOperationPending(id) &&
            !c.isOperationReady(id) &&
            !c.isOperationDone(id) &&
            c.getTimestamp(id) == 0
        );
    }

    receive() external payable {}
}

